    {
        worldOwner = msg.sender; 
        ticketPrice = 0.0101 * 10**18;
        maxTickets = 10;
		_direction = 0;
        lottoIndex = 1;
        lastTicketTime = 0;
        numtickets = 0;
        totalBounty = 0;
    }
